void TrajectoryOptimizer::on_traj([[maybe_unused]] const CandidateTrajectories::ConstSharedPtr msg)
{
  autoware_utils_debug::ScopedTimeTrack st(__func__, *time_keeper_);
  initialize_optimizers();

  current_odometry_ptr_ = sub_current_odometry_.take_data();
  current_acceleration_ptr_ = sub_current_acceleration_.take_data();

  if (!current_odometry_ptr_ || !current_acceleration_ptr_) {
    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000, "No odometry or acceleration data");
    return;
  }

  CandidateTrajectories output_trajectories = *msg;
  for (auto & trajectory : output_trajectories.candidate_trajectories) {
    // Create a fresh data instance per trajectory so semantic_speed_tracker is reset each time
    TrajectoryOptimizerData data;
    data.current_odometry = *current_odometry_ptr_;
    data.current_acceleration = *current_acceleration_ptr_;
    // Apply optimizations - plugins execute in order from plugin_names parameter
    for (auto & plugin : plugins_) {
      plugin->optimize_trajectory(trajectory.points, params_, data);
    }

    // Downstream Autoware modules dont properly support trajectories with less than 3 points. So we
    // return a dummy stopped trajectory instead.
    if (trajectory.points.size() < 3) {
      trajectory.points =
        utils::generate_three_point_stopped_trajectory(trajectory.points, data.current_odometry);
    }
  }

  trajectories_pub_->publish(output_trajectories);

  Trajectory output_trajectory;
  output_trajectory.header = output_trajectories.candidate_trajectories.front().header;
  output_trajectory.points = output_trajectories.candidate_trajectories.front().points;

  trajectory_pub_->publish(output_trajectory);
}

void TrajectoryOptimizer::initialize_optimizers()
{
  if (initialized_optimizers_) {
    return;
  }

  // Get plugin names from parameter
  const auto plugin_names = get_parameter("plugin_names").as_string_array();

  // Load each plugin in order
  for (const auto & plugin_name : plugin_names) {
    load_plugin(plugin_name);
  }
  initialized_optimizers_ = true;
}

void TrajectoryOptimizer::load_plugin(const std::string & plugin_name)
{
  try {
    auto plugin = plugin_loader_->createSharedInstance(plugin_name);

    // Check if plugin is already loaded
    for (const auto & p : plugins_) {
      if (plugin->get_name() == p->get_name()) {
        RCLCPP_WARN_STREAM(get_logger(), "Plugin '" << plugin_name << "' is already loaded.");
        return;
      }
    }

    // Initialize plugin with node context
    plugin->initialize(plugin_name, this, time_keeper_);

    plugins_.push_back(plugin);

    RCLCPP_INFO_STREAM(get_logger(), "Loaded plugin: " << plugin_name);
  } catch (const pluginlib::CreateClassException & e) {
    RCLCPP_ERROR_STREAM(
      get_logger(), "Failed to load plugin '" << plugin_name << "': " << e.what());
  } catch (const std::exception & e) {
    RCLCPP_ERROR_STREAM(
      get_logger(), "Unexpected error loading plugin '" << plugin_name << "': " << e.what());
  }
}

std::shared_ptr<T> createSharedInstance(const std::string & lookup_name);

/// Create an instance of a desired class.
/**
 * Implicitly calls loadLibraryForClass() to increment the library counter.
 *
 * Deleting the instance and calling unloadLibraryForClass() is automatically
 * handled by the unique pointer.

virtual void initialize(
  const std::string & name, rclcpp::Node * node_ptr,
  const std::shared_ptr<autoware_utils_debug::TimeKeeper> & time_keeper)
{
  name_ = name;
  node_ptr_ = node_ptr;
  time_keeper_ = time_keeper;
  set_up_params();
  std::cerr << "initialized TrajectoryOptimizerPlugin: " << name_ << std::endl;
}

TrajectoryPoints generate_three_point_stopped_trajectory(
  const TrajectoryPoints & input_traj, const Odometry & odom)
{
  // ego vehicle is moving, returning a dummy trajectory might be dangerous
  constexpr double moving_threshold_mps{0.1};
  if (odom.twist.twist.linear.x > moving_threshold_mps) {
    log_debug_throttle(
      "Skip generating three point stopped trajectory since the vehicle is moving");
    return input_traj;
  }

  log_debug_throttle("Generated three-point stopped trajectory");

  TrajectoryPoint base_link_point;
  base_link_point.time_from_start = rclcpp::Duration::from_seconds(0.);
  base_link_point.pose = odom.pose.pose;
  base_link_point.longitudinal_velocity_mps = 0.0;
  base_link_point.acceleration_mps2 = 0.0;

  TrajectoryPoint offset_point_1 = base_link_point;
  TrajectoryPoint offset_point_2 = base_link_point;

  constexpr double offset_x1{0.5};
  constexpr double offset_x2{1.0};

  offset_point_1.pose = autoware_utils_geometry::calc_offset_pose(
    base_link_point.pose, /*offset_x*/ offset_x1, /*offset_y*/ 0., /*offset_z*/ 0.);
  offset_point_2.pose = autoware_utils_geometry::calc_offset_pose(
    base_link_point.pose, /*offset_x*/ offset_x2, /*offset_y*/ 0., /*offset_z*/ 0.);
  return {base_link_point, offset_point_1, offset_point_2};
}

geometry_msgs::msg::Pose calc_offset_pose(
  const geometry_msgs::msg::Pose & p, const double x, const double y, const double z,
  const double yaw)
{
  geometry_msgs::msg::Pose pose;
  geometry_msgs::msg::Transform transform;
  transform.translation = create_translation(x, y, z);
  transform.rotation = create_quaternion_from_yaw(yaw);
  tf2::Transform tf_pose;
  tf2::Transform tf_offset;
  tf2::fromMsg(transform, tf_offset);
  tf2::fromMsg(p, tf_pose);
  tf2::toMsg(tf_pose * tf_offset, pose);
  return pose;
}

geometry_msgs::msg::Vector3 create_translation(const double x, const double y, const double z)
{
  geometry_msgs::msg::Vector3 v;
  v.x = x;
  v.y = y;
  v.z = z;
  return v;
}

geometry_msgs::msg::Quaternion create_quaternion_from_yaw(const double yaw)
{
  tf2::Quaternion q;
  q.setRPY(0, 0, yaw);
  return tf2::toMsg(q);
}
